  update eldervale_private.settings set revision=revision+1 where id returning revision into rev;
  update eldervale_private.entities set revision=rev,data=data||jsonb_build_object('name',case data->>'name' when 'Mithril rocks' then 'Moonsilver rocks' when 'Adamantite rocks' then 'Verdite rocks' when 'Runite rocks' then 'Tidestone rocks' end)
   where data->>'blueprint'='professions-v1' and data->>'template'='rock' and data->>'name' in('Mithril rocks','Adamantite rocks','Runite rocks');
 end if;
